import 'package:flutter/material.dart';
import 'dashboard_service.dart';

class StudentDashboard extends StatefulWidget{const StudentDashboard({super.key});@override State<StudentDashboard>createState()=>_StudentDashboardState();}
class _StudentDashboardState extends State<StudentDashboard>{final s=DashboardService();bool loading=true;String? error;Map<String,dynamic> d={};@override void initState(){super.initState();load();}Future<void>load()async{try{final x=await s.studentOverview();if(mounted)setState((){d=x;loading=false;});}catch(e){if(mounted)setState((){error=e.toString();loading=false;});}}@override Widget build(BuildContext c){if(loading)return const Center(child:CircularProgressIndicator());if(error!=null)return Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Text(error!),FilledButton(onPressed:load,child:const Text('Retry'))]));final a=Map<String,dynamic>.from((d['attendance']as Map?)??{});return RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.all(16),children:[Text('My Dashboard',style:Theme.of(c).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),Row(children:[Expanded(child:_card(c,'Attendance','${a['attendancePercent']??0}%',Icons.fact_check)),Expanded(child:_card(c,'Fees','₹${d['outstanding']??0}',Icons.account_balance_wallet))]),const SizedBox(height:14),Card(child:ListTile(leading:const Icon(Icons.menu_book),title:const Text('Homework'),subtitle:Text('${(d['homework']as List?)?.length??0} recent items'))),Card(child:ListTile(leading:const Icon(Icons.schedule),title:const Text('Timetable'),subtitle:const Text('Your class timetable and subjects')))]));}Widget _card(BuildContext c,String t,String v,IconData i)=>TweenAnimationBuilder<double>(tween:Tween(begin:0,end:1),duration:const Duration(milliseconds:500),builder:(x,n,ch)=>Transform.scale(scale:.92+.08*n,child:Card(child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(i),const SizedBox(height:7),Text(v,style:Theme.of(c).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text(t)])))));}
